import logging
from abc import ABCMeta, abstractmethod, abstractproperty

import six
from typing import Optional, List, Union, Any  # noqa: F401

from .cu import CU  # noqa: F401
from .du import DU, VDU  # noqa: F401
from ..cloud_hosting import CloudDeployment  # noqa: F401
from ..dcap import DcapRnD, DcapBasic  # noqa: F401


@six.add_metaclass(ABCMeta)
class gNB(object):
    """List of gnb ({1}*CU+DU) belonging to a testline with a reference
     to an optional control node on which the deployment is made"""

    @abstractmethod
    def __init__(self, cu, instance_id=None, global_bts_id=None, dcap=None):
        # type: (CU, Optional[int], Optional[int], Optional[Union[DcapRnD, DcapBasic]]) -> None
        """

        :param CU cu: CU (Central Unit) class instance object
        :param int instance_id: (optional) Instance Identifier of the MRBTS object. Defaults to None.
        :param int global_bts_id: (optional) Instance identifier of the NRBTS object.
          It is also used as a telecom parameter of the 3GPP Global gNB ID. Defaults to None.
        :param Optional[Union[DcapRnD, DcapBasic]] dcap: (optional) Instance of DCAP object related to gnb
        """
        self.cu = cu
        self.instance_id = instance_id
        self.global_bts_id = global_bts_id
        self.dcap = dcap

    @abstractproperty
    def oam_ip(self):
        raise NotImplementedError()


class ClassicalBts(gNB):
    def __init__(self,
                 dus,  # type: List[DU],
                 cu,  # type: CU
                 instance_id=None,  # type: Optional[int]
                 global_bts_id=None,  # type: Optional[int]
                 master=None,  # type: Optional[Any]
                 slave=None,  # type: Optional[Any]
                 dcap=None  # type: Optional[Union[DcapRnD, DcapBasic]]
                 ):
        """

        :param List[DU] du: DU (Distributed Unit) class instance object
        :param CU cu: CU (Central Unit) class instance object
        :param int instance_id: (optional) Instance Identifier of the MRBTS object. Defaults to None.
        :param int global_bts_id: (optional) Instance identifier of the NRBTS object.
          It is also used as a telecom parameter of the 3GPP Global gNB ID. Defaults to None.
        :param Optional[Any] slave: Another gNB, eNB, nB or Bts2G
          which is connected to it in slave role
        :param Optional[Any] master: Another gNB, eNB, nB or Bts2G
          which is connected to it in master role
        :param Optional[Union[DcapRnD, DcapBasic]] dcap: (optional) Instance of DCAP object related to gnb
        """
        super(ClassicalBts, self).__init__(cu, instance_id=instance_id, global_bts_id=global_bts_id, dcap=dcap)
        assert len(dus) == 1, "In ClassicalBts list of dus must hold exactly one instance"
        self.dus = dus
        self.slave = slave
        self.master = master

    # TODO: delete this property in next major release
    @property
    def du(self):
        deprecation_msg = "As of version 7.0.0 of taf.config.testline accessing DU should be done by: gnb[x].dus[0]. " \
                          "Access by gnb[x].du is deprecated adn will be removed in future."
        logging.warning(deprecation_msg)
        return self.dus[0]

    @property
    def oam_ip(self):
        return self.cu.backhaul_site_oam_ip


class CloudBts(gNB):
    def __init__(self,
                 cu,  # type: CU
                 cloud_deployment,  # type: Optional[CloudDeployment]
                 dus=None,  # type: Optional[List[Union[DU, VDU]]]
                 vnf_name=None,  # type: Optional[str]
                 instance_id=None,  # type: Optional[int]
                 global_bts_id=None,  # type: Optional[int]
                 dcap=None  # type: Optional[Union[DcapRnD, DcapBasic]]
                 ):
        """

        :param CU cu: CU (Central Unit) class instance object
        :param CloudDeployment cloud_deployment: CloudDeployment class instance object
        :param Optional[List[Union[DU, VDU]]] dus: List of DU (Distributed Unit) class instance objects
        :param str vnf_name: Name of the vnf (Virtual Network Function)
        :param int instance_id: instance_id parameter is deprecated and will be removed in the future.
            For CloudBts configuration, instance_id should be defined separately for CU and DUs.
        :param int global_bts_id: global_bts_id parameter is deprecated and will be removed in the future.
            For CloudBts configuration, global_bts_id should be defined separately for CU and DUs.
        :param Optional[Union[DcapRnD, DcapBasic]] dcap: (optional) Instance of DCAP object related to gnb
        """
        super(CloudBts, self).__init__(cu, instance_id=instance_id, global_bts_id=global_bts_id, dcap=dcap)
        self.dus = dus
        self.vnf_name = vnf_name
        self.cloud_deployment = cloud_deployment

        if self.instance_id is not None:
            logging.warning('instance_id parameter is deprecated and will be removed in the future. '
                            'For CloudBts configuration, instance_id should be defined separately for CU and DUs.')
        if self.global_bts_id is not None:
            logging.warning('global_bts_id parameter is deprecated and will be removed in the future. '
                            'For CloudBts configuration, global_bts_id should be defined separately for CU and DUs.')

    @property
    def oam_ip(self):
        oam_ip = 'oam_ip'
        params = 'parameters'

        def has_oam_ip(configuration):
            return (configuration is not None
                    and params in configuration
                    and oam_ip in configuration[params])

        vnfs = [vnf for vnf in self.cloud_deployment.vnfs
                if has_oam_ip(vnf.configuration_data)]

        if len(vnfs):
            # We are returning oam ip from the first vnf because we
            # assume that every vnf has the same exact oam ip value.
            return vnfs[0].configuration_data[params][oam_ip]
        else:
            return self.cu.backhaul_site_oam_ip
